private void bind(Configure configure) throws Throwable {
    long start = System.currentTimeMillis();

    if (!isBindRef.compareAndSet(false, true)) {
        throw new IllegalStateException("already bind");
    }

    // init random port
    if (configure.getTelnetPort() != null && configure.getTelnetPort() == 0) {
        int newTelnetPort = SocketUtils.findAvailableTcpPort();
        configure.setTelnetPort(newTelnetPort);
        logger().info("generate random telnet port: " + newTelnetPort);
    }

    if (configure.getHttpPort() != null && configure.getHttpPort() == 0) {
        int newHttpPort = SocketUtils.findAvailableTcpPort();
        configure.setHttpPort(newHttpPort);
        logger().info("generate random http port: " + newHttpPort);
    }

    // try to find appName
    if (configure.getAppName() == null) {
        configure.setAppName(System
        .getProperty(ArthasConstants.PROJECT_NAME,
        System.getProperty(ArthasConstants
        .SPRING_APPLICATION_NAME, null)));
    }

    try {
        if (configure.getTunnelServer() != null) {
            tunnelClient = new TunnelClient();
            tunnelClient.setAppName(configure.getAppName());
            tunnelClient.setId(configure.getAgentId());
            tunnelClient.setTunnelServerUrl(configure.getTunnelServer());
            tunnelClient.setVersion(ArthasBanner.version());

            ChannelFuture channelFuture = tunnelClient.start();
            channelFuture.await(10, TimeUnit.SECONDS);
        }
    } catch (Throwable t) {
        logger().error("start tunnel client error", t);
    }

    try {
        ShellServerOptions options = new ShellServerOptions()
        .setInstrumentation(instrumentation)
        .setPid(PidUtils.currentLongPid())
        .setWelcomeMessage(ArthasBanner.welcome());

        if (configure.getSessionTimeout() != null) {
            options.setSessionTimeout(configure.getSessionTimeout() * 1000);
        }

        this.httpSessionManager = new HttpSessionManager();

        if (IPUtils.isAllZeroIP(configure.getIp()) && StringUtils.isBlank(configure.getPassword())) {
            // 当 listen 0.0.0.0 时，强制生成密码，防止被远程连接
            String errorMsg = "Listening on 0.0.0.0 is very dangerous! External users can connect to your machine! "
             + "No password is currently configured. " 
             + "Therefore, a default password is generated, "
             + "and clients need to use the password to connect!";
            AnsiLog.error(errorMsg);
            configure.setPassword(StringUtils.randomString(64));
            AnsiLog.error("Generated arthas password: " + configure.getPassword());
            logger().error(errorMsg);
            logger().info("Generated arthas password: " + configure.getPassword());
        }

        this.securityAuthenticator = new SecurityAuthenticatorImpl(configure.getUsername(), configure.getPassword());
        shellServer = new ShellServerImpl(options);

        List<String> disabledCommands = new ArrayList<String>();

        if (configure.getDisabledCommands() != null) {
            String[] strings = StringUtils.tokenizeToStringArray(configure.getDisabledCommands(), ",");

            if (strings != null) {
                disabledCommands.addAll(Arrays.asList(strings));
            }
        }

        BuiltinCommandPack builtinCommands = new BuiltinCommandPack(disabledCommands);
        List<CommandResolver> resolvers = new ArrayList<CommandResolver>();
        resolvers.add(builtinCommands);
        //worker group
        workerGroup = new NioEventLoopGroup(new DefaultThreadFactory("arthas-TermServer", true));

        // TODO: discover user provided command resolver
        if (configure.getTelnetPort() != null && configure.getTelnetPort() > 0) {
            logger().info("try to bind telnet server, host: {}, port: {}.", configure.getIp(), configure.getTelnetPort());
            shellServer.registerTermServer(new HttpTelnetTermServer(configure.getIp(), 
            configure.getTelnetPort(),
            options.getConnectionTimeout(), 
            workerGroup, httpSessionManager));
        } else {
            logger().info("telnet port is {}, skip bind telnet server.", configure.getTelnetPort());
        }

        if (!(configure.getHttpPort() != null && configure.getHttpPort() > 0)) {
            // listen local address in VM communication
            if (configure.getTunnelServer() != null) {
                shellServer.registerTermServer(new HttpTermServer(configure.getIp(), 
                configure.getHttpPort(),
                options.getConnectionTimeout(), 
                workerGroup, httpSessionManager));
            }

            logger().info("http port is {}, skip bind http server.", configure.getHttpPort());
        } else {
            logger().info("try to bind http server, host: {}, port: {}.", configure.getIp(), configure.getHttpPort());
            shellServer.registerTermServer(new HttpTermServer(configure.getIp(), 
            configure.getHttpPort(),
            options.getConnectionTimeout(), 
            workerGroup, httpSessionManager));
        } 

        for (CommandResolver resolver : resolvers) {
            shellServer.registerCommandResolver(resolver);
        }

        shellServer.listen(new BindHandler(isBindRef));

        if (!isBind()) {
            throw new IllegalStateException("Arthas failed to bind telnet or http port! Telnet port: "
             + String.valueOf(configure.getTelnetPort()) + ", http port: "
             + String.valueOf(configure.getHttpPort()));
        }

        //http api session manager
        sessionManager = new SessionManagerImpl(options, shellServer.getCommandManager(), shellServer.getJobController());
        //http api handler
        httpApiHandler = new HttpApiHandler(historyManager, sessionManager);
        logger().info("as-server listening on network={};telnet={};http={};timeout={};", 
        configure.getIp(), configure.getTelnetPort(), 
        configure.getHttpPort(), 
        options.getConnectionTimeout());

        // 异步回报启动次数
        if (configure.getStatUrl() != null) {
            logger().info("arthas stat url: {}", configure.getStatUrl());
        }

        UserStatUtil.setStatUrl(configure.getStatUrl());
        UserStatUtil.setAgentId(configure.getAgentId());
        UserStatUtil.arthasStart();

        try {
            SpyAPI.init();
        } catch (Throwable e) {
        // ignore
        }

        logger().info("as-server started in {} ms", System.currentTimeMillis() - start);
    } catch (Throwable e) {
        logger().error("Error during start as-server", e);
        destroy();
        throw e;
    }
}

private int __read(boolean mayBlock) throws IOException {
    int ch;

    while (true) {
        // If there is no more data AND we were told not to block,
        // just return WOULD_BLOCK (-2). (More efficient than exception.)
        if (!mayBlock && super.available() == 0) {
            return WOULD_BLOCK;
        }
        // Otherwise, exit only when we reach end of stream.
        if ((ch = super.read()) < 0) {
            return EOF;
        }

        ch = (ch & 0xff); /* Code Section added for supporting AYT (start)*/
        synchronized (__client) {
            __client._processAYTResponse();
        }/* Code Section added for supporting AYT (end)*//* Code Section added for supporting spystreams (start)*/
        __client._spyRead(ch); /* Code Section added for supporting spystreams (end)*/

        switch (__receiveState) {
            case _STATE_CR : 
                if (ch == '\0') {
                    // Strip null
                    continue;
                }
            // How do we handle newline after cr?
            //  else if (ch == '\n' && _requestedDont(TelnetOption.ECHO) &&
            // Handle as normal data by falling through to _STATE_DATA case

            //$FALL-THROUGH$
            case _STATE_DATA : 
                if (ch == TelnetCommand.IAC) {
                    __receiveState = _STATE_IAC;
                    continue;
                }
                if (ch == '\r') {
                    synchronized (__client) {
                        if (__client._requestedDont(TelnetOption.BINARY)) {
                            __receiveState = _STATE_CR;
                        } else {
                            __receiveState = _STATE_DATA;
                        }
                    }
                } else {
                    __receiveState = _STATE_DATA;
                }
                break;
            case _STATE_IAC : 
                switch (ch) {
                    case TelnetCommand.WILL : 
                        __receiveState = _STATE_WILL;
                        continue;
                    case TelnetCommand.WONT : 
                        __receiveState = _STATE_WONT;
                        continue;
                    case TelnetCommand.DO : 
                        __receiveState = _STATE_DO;
                        continue;
                    case TelnetCommand.DONT : 
                        __receiveState = _STATE_DONT;
                        continue; /* TERMINAL-TYPE option (start)*/
                    case TelnetCommand.SB : 
                        __suboption_count = 0;
                        __receiveState = _STATE_SB;
                        continue; /* TERMINAL-TYPE option (end)*/
                    case TelnetCommand.IAC : 
                        __receiveState = _STATE_DATA;
                        break; // exit to enclosing switch to return IAC from read

                    case TelnetCommand.SE : 
                        // unexpected byte! ignore it (don't send it as a command)
                        __receiveState = _STATE_DATA;
                        continue;
                    default : 
                        __receiveState = _STATE_DATA;
                        __client._processCommand(ch); // Notify the user

                        continue; // move on the next char

                }
                break; // exit and return from read

            case _STATE_WILL : 
                synchronized (__client) {
                    __client._processWill(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_WONT : 
                synchronized (__client) {
                    __client._processWont(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_DO : 
                synchronized (__client) {
                    __client._processDo(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_DONT : 
                synchronized (__client) {
                    __client._processDont(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue; /* TERMINAL-TYPE option (start)*/
            case _STATE_SB : 
                switch (ch) {
                    case TelnetCommand.IAC : 
                        __receiveState = _STATE_IAC_SB;
                        continue;
                    default : 
                        // store suboption char
                        if (__suboption_count < __suboption.length) {
                            __suboption[__suboption_count++] = ch;
                        }
                        break;
                }
                __receiveState = _STATE_SB;
                continue;
            case _STATE_IAC_SB : // IAC received during SB phase
                switch (ch) {
                    case TelnetCommand.SE : 
                        synchronized (__client) {
                            __client._processSuboption(__suboption, __suboption_count);
                            __client._flushOutputStream();
                        }
                        __receiveState = _STATE_DATA;
                        continue;
                    case TelnetCommand.IAC : // De-dup the duplicated IAC
                        if (__suboption_count < __suboption.length) {
                            __suboption[__suboption_count++] = ch;
                        }
                        break;
                    default :            
                        // unexpected byte! ignore it
                        break;
                }
                __receiveState = _STATE_SB;
                continue; /* TERMINAL-TYPE option (end)*/
        }

        break;
    }

    return ch;
}

@StyleRes
public static int getSettingsThemeStyle(final Context context) {
    final Resources res = context.getResources();
    final String lightTheme = res.getString(R.string.light_theme_key);
    final String blackTheme = res.getString(R.string.black_theme_key);
    final String automaticDeviceTheme = res.getString(R.string.auto_device_theme_key);
    final String selectedTheme = getSelectedThemeKey(context);

    if (selectedTheme.equals(lightTheme)) {
        return R.style.LightSettingsTheme;
    } else if (selectedTheme.equals(blackTheme)) {
        return R.style.BlackSettingsTheme;
    } else if (selectedTheme.equals(automaticDeviceTheme)) {
        if (isDeviceDarkThemeEnabled(context)) {
            // use the dark theme variant preferred by the user
            final String selectedNightTheme = getSelectedNightThemeKey(context);

            if (selectedNightTheme.equals(blackTheme)) {
                return R.style.BlackSettingsTheme;
            } else {
                return R.style.DarkSettingsTheme;
            }
        } else {
            // there is only one day theme
            return R.style.LightSettingsTheme;
        }
    } else {
        // default to dark theme
        return R.style.DarkSettingsTheme;
    }

}

private static Object process(final RedisInputStream is) {

    final byte b = is.readByte();

    // System.out.println("BYTE: " + (char) b);
    switch (b) {
        case PLUS_BYTE : 
            return is.readLineBytes();
        case DOLLAR_BYTE : 
        case EQUAL_BYTE : 
            return processBulkReply(is);
        case ASTERISK_BYTE : 
            return processMultiBulkReply(is);
        case UNDERSCORE_BYTE : 
            return is.readNullCrLf();
        case HASH_BYTE : 
            return is.readBooleanCrLf();
        case COLON_BYTE : 
            return is.readLongCrLf();
        case COMMA_BYTE : 
            return is.readDoubleCrLf();
        case LEFT_BRACE_BYTE : 
            return is.readBigIntegerCrLf();
        case PERCENT_BYTE : // TODO: currently just to start working with HELLO

            return processMapKeyValueReply(is);
        case TILDE_BYTE : // TODO:

            return processMultiBulkReply(is);
        case GREATER_THAN_BYTE : 
            return processMultiBulkReply(is);
        case MINUS_BYTE : 
            processError(is);
            return null;
        // TODO: Blob error '!'
        default : 
            throw new JedisConnectionException("Unknown reply: " + (char) b);
    }
}

public static void addImageToDocument(PDDocument doc, 
        PDImageXObject image, String fitOption, boolean autoRotate)throws IOException {
    boolean imageIsLandscape = image.getWidth() > image.getHeight();
    PDRectangle pageSize = PDRectangle.A4;
    if (autoRotate && imageIsLandscape) {
        pageSize = new PDRectangle(pageSize.getHeight(), pageSize.getWidth());
    }

    if ("fitDocumentToImage".equals(fitOption)) {
        pageSize = new PDRectangle(image.getWidth(), image.getHeight());
    }

    PDPage page = new PDPage(pageSize);
    doc.addPage(page);

    float pageWidth = page.getMediaBox().getWidth();
    float pageHeight = page.getMediaBox().getHeight();

    try (PDPageContentStream contentStream = 
    new PDPageContentStream(doc, page, AppendMode.APPEND, true, true)) {
        if ("fillPage".equals(fitOption) || "fitDocumentToImage".equals(fitOption)) {
            contentStream.drawImage(image, 0, 0, pageWidth, pageHeight);
        } else if ("maintainAspectRatio".equals(fitOption)) {
            float imageAspectRatio = (float) image.getWidth() / (float) image.getHeight();
            float pageAspectRatio = pageWidth / pageHeight;
            float scaleFactor = 1.0f;
            if (imageAspectRatio > pageAspectRatio) {
                scaleFactor = pageWidth / image.getWidth();
            } else {
                scaleFactor = pageHeight / image.getHeight();
            }

            float xPos = (pageWidth - (image.getWidth() * scaleFactor)) / 2;
            float yPos = (pageHeight - (image.getHeight() * scaleFactor)) / 2;
            contentStream.drawImage(image, xPos, yPos, image.getWidth() * scaleFactor, image.getHeight() * scaleFactor);
        }

    } catch (IOException e) {
        log.error("Error adding image to PDF", e);
        throw e;
    }
}

@Override
public Connection getConnection() {
    List<ConnectionPool> pools = getShuffledNodesPool();
    JedisException suppressed = null;
    for (ConnectionPool pool : pools) {
        Connection jedis = null;
        try {
            jedis = pool.getResource();
            if (jedis == null) {
                continue;
            }

            jedis.ping();
            return jedis;
        } catch (JedisException ex) {
            if (suppressed == null) { // remembering first suppressed exception

                suppressed = ex;
            }
            if (jedis != null) {
                jedis.close();
            }
        }
    }

    JedisException noReachableNode = new JedisException("No reachable shard.");
    if (suppressed != null) {
        noReachableNode.addSuppressed(suppressed);
    }

    throw noReachableNode;
}

private static void handleError(final Context context, final ErrorInfo errorInfo) {
    if (errorInfo.getThrowable() != null) {
        errorInfo.getThrowable().printStackTrace();
    }

    if (errorInfo.getThrowable() instanceof ReCaptchaException) {
        Toast.makeText(context, R.string.recaptcha_request_toast, Toast.LENGTH_LONG).show();

        // Starting ReCaptcha Challenge Activity
        final Intent intent = new Intent(context, ReCaptchaActivity.class);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        context.startActivity(intent);
    } else if (errorInfo.getThrowable() != null && ExceptionUtils.isNetworkRelated(errorInfo.getThrowable())) {
        Toast.makeText(context, R.string.network_error, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof AgeRestrictedContentException) {
        Toast.makeText(context, R.string.restricted_video_no_stream, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof GeographicRestrictionException) {
        Toast.makeText(context, R.string.georestricted_content, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof PaidContentException) {
        Toast.makeText(context, R.string.paid_content, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof PrivateContentException) {
        Toast.makeText(context, R.string.private_content, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof SoundCloudGoPlusContentException) {
        Toast.makeText(context, R.string.soundcloud_go_plus_content, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof YoutubeMusicPremiumContentException) {
        Toast.makeText(context, R.string.youtube_music_premium_content, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof ContentNotAvailableException) {
        Toast.makeText(context, R.string.content_not_available, Toast.LENGTH_LONG).show();
    } else if (errorInfo.getThrowable() instanceof ContentNotSupportedException) {
        Toast.makeText(context, R.string.content_not_supported, Toast.LENGTH_LONG).show();
    } else {
        ErrorUtil.createNotification(context, errorInfo);
    }


    if (context instanceof RouterActivity) {
        ((RouterActivity) context).finish();
    }
}

@Override
public byte[] transform(ClassLoader loader, 
        String className, Class<?> classBeingRedefined,
        ProtectionDomain protectionDomain, 
        byte[] classfileBuffer) throws IllegalClassFormatException {
    if (className == null) {
        return null;
    }
    className = className.replace('/', '.');

    List<RetransformEntry> allRetransformEntries = allRetransformEntries();
    // 倒序，因为要执行的配置生效
    ListIterator<RetransformEntry> listIterator = allRetransformEntries.listIterator(allRetransformEntries.size());

    while (listIterator.hasPrevious()) {
        RetransformEntry retransformEntry = listIterator.previous();
        int id = retransformEntry.getId();
        // 判断类名是否一致
        boolean updateFlag = false;
        // 类名一致，则看是否要比较 loader，如果不需要比较 loader，则认为成功
        if (className.equals(retransformEntry.getClassName())) {
            updateFlag = retransformEntry.getClassLoaderClass() != null || retransformEntry.getHashCode() != null ? isLoaderMatch(retransformEntry, loader) : true; 
        }

        if (!updateFlag) { 
            continue; 
        }  
        logger.info("RetransformCommand match class: {}, id: {}, classLoaderClass: {}, hashCode: {}",
                className, id, retransformEntry
                .getClassLoaderClass(), 
                retransformEntry.getHashCode());
        retransformEntry.incTransformCount();
        return retransformEntry.getBytes();
    }
    return null;
}

public static void openVideoDetailFragment(@NonNull final Context context,
        @NonNull final FragmentManager fragmentManager,
        final int serviceId,@Nullable final String url,
        @NonNull final String title,
        @Nullable final PlayQueue playQueue,
        final boolean switchingPlayers) {
    final boolean autoPlay;
    @Nullable final PlayerType playerType = PlayerHolder.getInstance().getType();

    autoPlay = playerType == null
            ? PlayerHelper.isAutoplayAllowedByUser(context)
             : switchingPlayers ? PlayerHolder.getInstance().isPlaying()
             : playerType == PlayerType.MAIN
            ? PlayerHelper.isAutoplayAllowedByUser(context)
             : false; 

    final RunnableWithVideoDetailFragment onVideoDetailFragmentReady = detailFragment -> {
        expandMainPlayer(detailFragment.requireActivity());
        detailFragment.setAutoPlay(autoPlay);
        if (switchingPlayers) {
            // Situation when user switches from players to main player. All needed data is
            // here, we can start watching (assuming newQueue equals playQueue).
            // Starting directly in fullscreen if the previous player type was popup.
            detailFragment.openVideoPlayer(playerType == PlayerType.POPUP || PlayerHelper.isStartMainPlayerFullscreenEnabled(context));
        } else {
            detailFragment.selectAndLoadVideo(serviceId, url, title, playQueue);
        }
        detailFragment.scrollToTop();
    };
    final Fragment fragment = fragmentManager.findFragmentById(R.id.fragment_player_holder);

    if (fragment instanceof VideoDetailFragment && fragment.isVisible()) {
        onVideoDetailFragmentReady.run((VideoDetailFragment) fragment);
    } else {
        // Specify no url here, otherwise the VideoDetailFragment will start loading the
        // stream automatically if it's the first time it is being opened, but then
        // onVideoDetailFragmentReady will kick in and start another loading process.
        // See VideoDetailFragment.wasCleared() and its usage in doInitialLoadLogic().
        final VideoDetailFragment instance = VideoDetailFragment.getInstance(serviceId, null, title, playQueue);
        instance.setAutoPlay(autoPlay);
        defaultTransaction(fragmentManager).replace(R.id.fragment_player_holder, instance).runOnCommit(() -> onVideoDetailFragmentReady.run(instance)).commit();
    }
}

void establishConnection(int threadId, HttpURLConnection conn) throws IOException, HttpError {
  int statusCode = conn.getResponseCode();
  if (DEBUG) {
    Log.d(TAG, threadId + ":[request]  Range=" + conn.getRequestProperty("Range"));

    Log.d(TAG, threadId + ":[response] Code=" + statusCode);

    Log.d(TAG, threadId + ":[response] Content-Length=" + conn.getContentLength());

    Log.d(TAG, threadId + ":[response] Content-Range=" + conn.getHeaderField("Content-Range"));
  }

  switch (statusCode) {
    case 204 : 
    case 205 : 
    case 207 : 
      throw new HttpError(statusCode);
    case 416 : 
      return; // let the download thread handle this error

    default : 
      if (statusCode < 200) {
        throw new HttpError(statusCode);
      }

      if (statusCode > 299) {
        throw new HttpError(statusCode);
      }

  }
}

public static Map<String, String> toStringMap(Map<String, Object> input, boolean stringEscape) {
    Map<String, String> output = new HashMap<>(input.size());
    for (Map.Entry<String, Object> entry:input.entrySet()) {
        String key = entry.getKey();
        Object obj = entry.getValue();
        if (key == null || obj == null) {
            throw new NullPointerException("A null argument cannot be sent to Redis.");
        }

        String str;

        if (obj instanceof byte[]) {
            str = SafeEncoder.encode((byte[]) obj);
        } else if (obj instanceof redis.clients.jedis.GeoCoordinate) {
            redis.clients.jedis.GeoCoordinate geo = (redis.clients.jedis.GeoCoordinate) obj;
            str = geo.getLongitude() + "," + geo.getLatitude();
        } else if (obj instanceof String) {
            str = stringEscape ? escape((String) obj):(String) obj;
        } else {
            str = String.valueOf(obj);
        }

        output.put(key, str);
    }

    return output;
}

public List<ThreadVO> sample(Collection<ThreadVO> originThreads) {
    List<ThreadVO> threads = new ArrayList<ThreadVO>(originThreads);
    // Sample CPU
    if (lastCpuTimes.isEmpty()) {
        lastSampleTimeNanos = System.nanoTime();

        for (ThreadVO thread:threads) {
            if (thread.getId() > 0) {
                long cpu = threadMXBean.getThreadCpuTime(thread.getId());
                lastCpuTimes.put(thread, cpu);
                thread.setTime(cpu / 1000000);
            }
        }

        // add internal threads
        Map<String, Long> internalThreadCpuTimes = getInternalThreadCpuTimes();
        if (internalThreadCpuTimes != null) {
            for (Map.Entry<String, Long> entry:internalThreadCpuTimes.entrySet()) {
                String key = entry.getKey();
                ThreadVO thread = createThreadVO(key);
                thread.setTime(entry.getValue() / 1000000);
                threads.add(thread);
                lastCpuTimes.put(thread, entry.getValue());
            }
        }

        //sort by time
        Collections.sort(threads, new Comparator<ThreadVO>() {
            @Override
            public int compare(ThreadVO o1, ThreadVO o2) {
                long l1 = o1.getTime();
                long l2 = o2.getTime();
                if (l1 < l2) {
                    return 1;
                } else if (l1 > l2) {
                    return -1;
                } else {
                    return 0;
                }

            }});

        return threads;
    }

    // Resample
    long newSampleTimeNanos = System.nanoTime();
    Map<ThreadVO, Long> newCpuTimes = new HashMap<ThreadVO, Long>(threads.size());
    for (ThreadVO thread:threads) {
        if (thread.getId() > 0) {
            long cpu = threadMXBean.getThreadCpuTime(thread.getId());
            newCpuTimes.put(thread, cpu);
        }
    }

    // internal threads
    Map<String, Long> newInternalThreadCpuTimes = getInternalThreadCpuTimes();
    if (newInternalThreadCpuTimes != null) {
        for (Map.Entry<String, Long> entry:newInternalThreadCpuTimes.entrySet()) {
            ThreadVO threadVO = createThreadVO(entry.getKey());
            threads.add(threadVO);
            newCpuTimes.put(threadVO, entry.getValue());
        }
    }
    // Compute delta time
    final Map<ThreadVO, Long> deltas = new HashMap<ThreadVO, Long>(threads.size());
    for (ThreadVO thread:newCpuTimes.keySet()) {
        Long t = lastCpuTimes.get(thread);
        if (t == null) {
            t = 0L;
        }
        long time1 = t;
        long time2 = newCpuTimes.get(thread);
        if (time1 == -1) {
            time1 = time2;
        } else if (time2 == -1) {
            time2 = time1;
        }

        long delta = time2 - time1;
        deltas.put(thread, delta);
    }

    long sampleIntervalNanos = newSampleTimeNanos - lastSampleTimeNanos;

    // Compute cpu usage
    final HashMap<ThreadVO, Double> cpuUsages = new HashMap<ThreadVO, Double>(threads.size());
    for (ThreadVO thread:threads) {
        double cpu = sampleIntervalNanos == 0 ? 0:(Math.rint(deltas.get(thread) * 10000.0 / sampleIntervalNanos) / 100.0);
        cpuUsages.put(thread, cpu);
    }

    // Sort by CPU time : should be a rendering hint...
    Collections.sort(threads, new Comparator<ThreadVO>() {
        @Override
        public int compare(ThreadVO o1, ThreadVO o2) {
            long l1 = deltas.get(o1);
            long l2 = deltas.get(o2);
            if (l1 < l2) {
                return 1;
            } else if (l1 > l2) {
                return -1;
            } else {
                return 0;
            }

        }});

    for (ThreadVO thread:threads) {
        //nanos to mills
        long timeMills = newCpuTimes.get(thread) / 1000000;
        long deltaTime = deltas.get(thread) / 1000000;
        double cpu = cpuUsages.get(thread);
        thread.setCpu(cpu);
        thread.setTime(timeMills);
        thread.setDeltaTime(deltaTime);
    }

    lastCpuTimes = newCpuTimes;
    lastSampleTimeNanos = newSampleTimeNanos;
    return threads;
}

private void onBroadcastReceived(final Intent intent) {
    if (intent == null || intent.getAction() == null) {
        return;
    }
    if (DEBUG) {
        Log.d(TAG, "onBroadcastReceived() called with: intent = [" + intent + "]");
    }

    switch (intent.getAction()) {
        case AudioManager.ACTION_AUDIO_BECOMING_NOISY:
            pause();
            break;
        case ACTION_CLOSE:
            service.destroyPlayerAndStopService();
            break;
        case ACTION_PLAY_PAUSE:
            playPause();
            break;
        case ACTION_PLAY_PREVIOUS:
            playPrevious();
            break;
        case ACTION_PLAY_NEXT:
            playNext();
            break;
        case ACTION_FAST_REWIND:
            fastRewind();
            break;
        case ACTION_FAST_FORWARD:
            fastForward();
            break;
        case ACTION_REPEAT:
            cycleNextRepeatMode();
            break;
        case ACTION_SHUFFLE:
            toggleShuffleModeEnabled();
            break;
        case Intent.ACTION_CONFIGURATION_CHANGED:
            if (DEBUG) {
                Log.d(TAG, "ACTION_CONFIGURATION_CHANGED received");
            }
            break;
    }
    UIs.call(playerUi -> playerUi.onBroadcastReceived(intent));
}

@Override
public void onTextTracksChanged(@NonNull final Tracks currentTracks) {
    super.onTextTracksChanged(currentTracks);
    final boolean trackTypeTextSupported = !currentTracks.containsType(C.TRACK_TYPE_TEXT)
             || currentTracks.isTypeSupported(C.TRACK_TYPE_TEXT, false);

    if (getPlayer().getTrackSelector().getCurrentMappedTrackInfo() == null || !trackTypeTextSupported) {
        binding.captionTextView.setVisibility(View.GONE);
        return;
    }

    // Extract all loaded languages
    final List<Tracks.Group> textTracks = currentTracks.getGroups().stream()
            .filter(trackGroupInfo -> C.TRACK_TYPE_TEXT == trackGroupInfo.getType()).collect(Collectors.toList());
    final List<String> availableLanguages = textTracks.stream().map(Tracks.Group::getMediaTrackGroup).filter(textTrack -> textTrack.length > 0)
            .map(textTrack -> textTrack.getFormat(0).language).collect(Collectors.toList());
    // Find selected text track
    final Optional<Format> selectedTracks = textTracks.stream().filter(Tracks.Group::isSelected)
            .filter(info -> info.getMediaTrackGroup().length >= 1)
            .map(info -> info.getMediaTrackGroup().getFormat(0)).findFirst();

    // Build UI
    buildCaptionMenu(availableLanguages);
    if (player.getTrackSelector().getParameters().getRendererDisabled(player.getCaptionRendererIndex()) || selectedTracks.isEmpty()) {
        binding.captionTextView.setText(R.string.caption_none);
    } else {
        binding.captionTextView.setText(selectedTracks.get().language);
    }
    binding.captionTextView.setVisibility(availableLanguages.isEmpty() ? View.GONE : View.VISIBLE);
}

void drainLoop() {
  Observer<? super T> actual = this.downstream;
  int missed = 1;
  for (;;) {
    for (;;) {

      if (disposed) {
        singleItem = null;
        queue = null;
        return;
      }

      if (errors.get() != null) {
        singleItem = null;
        queue = null;
        errors.tryTerminateConsumer(actual);
        return;
      }
      int os = otherState;
      if (os == OTHER_STATE_HAS_VALUE) {
        T v = singleItem;
        singleItem = null;
        otherState = OTHER_STATE_CONSUMED_OR_EMPTY;
        os = OTHER_STATE_CONSUMED_OR_EMPTY;
        actual.onNext(v);
      }

      boolean d = mainDone;
      SimplePlainQueue<T> q = queue;
      T v = q != null ? q.poll() : null;
      boolean empty = v == null;
      if (d && empty && os == OTHER_STATE_CONSUMED_OR_EMPTY) {
        queue = null;
        actual.onComplete();
        return;
      }

      if (empty) {
        break;
      }
      actual.onNext(v);
    }
    missed = addAndGet(-missed);
    if (missed == 0) {
      break;
    }
  }
}

@SuppressLint("SwitchIntDef") // only fit, fill and zoom are supported by NewPipe

@ResizeMode
public static int nextResizeModeAndSaveToPrefs(final Player player,@ResizeMode final int resizeMode) {
    final int newResizeMode;

    switch (resizeMode) {
        case AspectRatioFrameLayout.RESIZE_MODE_FIT:
            newResizeMode = AspectRatioFrameLayout.RESIZE_MODE_FILL;
            break;
        case AspectRatioFrameLayout.RESIZE_MODE_FILL:
            newResizeMode = AspectRatioFrameLayout.RESIZE_MODE_ZOOM;
            break;
        case AspectRatioFrameLayout.RESIZE_MODE_ZOOM:
        default:
            newResizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT;
            break;
    }
    // save the new resize mode so it can be restored in a future session
    player.getPrefs().edit().putInt(player.getContext().getString(R.string.last_resize_mode), newResizeMode).apply();
    return newResizeMode;
}

@Override
public void onBroadcastReceived(final Intent intent) {
    super.onBroadcastReceived(intent);

    if (Intent.ACTION_CONFIGURATION_CHANGED.equals(intent.getAction())) {
        // Close it because when changing orientation from portrait
        // (in fullscreen mode) the size of queue layout can be larger than the screen size
        closeItemsList();
    } else if (ACTION_PLAY_PAUSE.equals(intent.getAction())) {
        // Ensure that we have audio-only stream playing when a user
        // started to play from notification's play button from outside of the app
        if (!fragmentIsVisible) {
            onFragmentStopped();
        }
    } else if (VideoDetailFragment.ACTION_VIDEO_FRAGMENT_STOPPED.equals(intent.getAction())) {
        fragmentIsVisible = false;

        onFragmentStopped();
    } else if (VideoDetailFragment.ACTION_VIDEO_FRAGMENT_RESUMED.equals(intent.getAction())) {
        // Restore video source when user returns to the fragment
        fragmentIsVisible = true;

        player.useVideoSource(true);
        // When a user returns from background, the system UI will always be shown even if
        // controls are invisible: hide it in that case
        if (!isControlsVisible()) {
            hideSystemUIIfNeeded();
        }
    }

}

public static void drawPlayException(TableElement table, ObjectVO throwableVO) {
  // 执行失败:输出失败状态
  table.row("IS-RETURN", "" + false);
  table.row("IS-EXCEPTION", "" + true); // 执行失败:输出失败异常信息
  Throwable cause;
  Throwable t = (Throwable) throwableVO.getObject();
  cause = t instanceof InvocationTargetException ? t.getCause() : t; 
  if (throwableVO.needExpand()) {
    table.row("THROW-EXCEPTION", new ObjectView(cause, throwableVO.expandOrDefault()).draw());
  } else {
    StringWriter stringWriter = new StringWriter();
    PrintWriter printWriter = new PrintWriter(stringWriter);
    try {
      cause.printStackTrace(printWriter);

      table.row("THROW-EXCEPTION", stringWriter.toString());
    } finally {
      printWriter.close();
    }
  }
}

@Override
public void onNext(T t) {
    if (done) {
        return;
    }

    boolean b;
    try {
        b = predicate.test(t);
    } catch (Throwable e) {
        Exceptions.throwIfFatal(e);
        upstream.cancel();
        upstream = SubscriptionHelper.CANCELLED;
        onError(e);
        return;
    }
    if (!b) {
        done = true;
        upstream.cancel();
        upstream = SubscriptionHelper.CANCELLED;
        downstream.onSuccess(false);
    }
}

private static String extractBasicHeader(String emlContent, String headerName) {
  try {
    String[] lines = emlContent.split("\r?\n");
    for (int i = 0; i < lines.length; i++) {
      String line = lines[i];
      if (line.toLowerCase().startsWith(headerName.toLowerCase())) {
        StringBuilder value = new StringBuilder(line.substring(headerName.length()).trim());
        // Handle multi-line headers
        for (int j = i + 1; j < lines.length; j++) {
          if (lines[j].startsWith(" ") || lines[j].startsWith("\t")) {
            value.append(" ").append(lines[j].trim());
          } else {
            break;
          }
        }
        // Apply MIME header decoding
        return safeMimeDecode(value.toString());
      }

      if (line.trim().isEmpty()) {
        break;
      }
    }
  } catch (RuntimeException e) {
    log.warn("Error extracting header '{}': {}", headerName, e.getMessage());
  }
  return "";
}

private int __read(boolean mayBlock) throws IOException{
    int ch;

    for (;;) {
        // If there is no more data AND we were told not to block,
        // just return WOULD_BLOCK (-2). (More efficient than exception.)
        if (!mayBlock && super.available() == 0) {
            return WOULD_BLOCK;
        }

        // Otherwise, exit only when we reach end of stream.
        if ((ch = super.read()) < 0) {
            return EOF;
        }

        ch = (ch & 0xff);/* Code Section added for supporting AYT (start)*/
        synchronized (__client) {
            __client._processAYTResponse();
        }/* Code Section added for supporting AYT (end)*//* Code Section added for supporting spystreams (start)*/
        __client._spyRead(ch);/* Code Section added for supporting spystreams (end)*/

        switch (__receiveState) {
            case _STATE_CR:
                if (ch == '\0') {
                    // Strip null
                    continue;
                }
            // How do we handle newline after cr?
            //  else if (ch == '\n' && _requestedDont(TelnetOption.ECHO) &&
            // Handle as normal data by falling through to _STATE_DATA case

            //$FALL-THROUGH$
            case _STATE_DATA:
                if (ch == TelnetCommand.IAC) {
                    __receiveState = _STATE_IAC;
                    continue;
                }

                if (ch == '\r') {
                    synchronized (__client) {
                        if (__client._requestedDont(TelnetOption.BINARY)) {
                            __receiveState = _STATE_CR;
                        } else {
                            __receiveState = _STATE_DATA;
                        }
                    }
                } else {
                    __receiveState = _STATE_DATA;
                }
                break;
            case _STATE_IAC:
                switch (ch) {
                    case TelnetCommand.WILL:
                        __receiveState = _STATE_WILL;
                        continue;
                    case TelnetCommand.WONT:
                        __receiveState = _STATE_WONT;
                        continue;
                    case TelnetCommand.DO:
                        __receiveState = _STATE_DO;
                        continue;
                    case TelnetCommand.DONT:
                        __receiveState = _STATE_DONT;
                        continue;/* TERMINAL-TYPE option (start)*/
                    case TelnetCommand.SB:
                        __suboption_count = 0;
                        __receiveState = _STATE_SB;
                        continue;/* TERMINAL-TYPE option (end)*/
                    case TelnetCommand.IAC:
                        __receiveState = _STATE_DATA;
                        break; // exit to enclosing switch to return IAC from read

                    case TelnetCommand.SE: // unexpected byte! ignore it (don't send it as a command)

                        __receiveState = _STATE_DATA;
                        continue;
                    default:
                        __receiveState = _STATE_DATA;
                        __client._processCommand(ch); // Notify the user

                        continue; // move on the next char

                }
                break; // exit and return from read

            case _STATE_WILL:
                synchronized (__client) {
                    __client._processWill(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_WONT:
                synchronized (__client) {
                    __client._processWont(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_DO:
                synchronized (__client) {
                    __client._processDo(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;
            case _STATE_DONT:
                synchronized (__client) {
                    __client._processDont(ch);
                    __client._flushOutputStream();
                }
                __receiveState = _STATE_DATA;
                continue;/* TERMINAL-TYPE option (start)*/
            case _STATE_SB:
                switch (ch) {
                    case TelnetCommand.IAC:
                        __receiveState = _STATE_IAC_SB;
                        continue;
                    default:
                        // store suboption char
                        if (__suboption_count < __suboption.length) {
                            __suboption[__suboption_count++] = ch;
                        }
                        break;
                }
                __receiveState = _STATE_SB;
                continue;
            case _STATE_IAC_SB: // IAC received during SB phase
                switch (ch) {
                    case TelnetCommand.SE:
                        synchronized (__client) {
                            __client._processSuboption(__suboption, __suboption_count);
                            __client._flushOutputStream();
                        }
                        __receiveState = _STATE_DATA;
                        continue;
                    case TelnetCommand.IAC: // De-dup the duplicated IAC
                        if (__suboption_count < __suboption.length) {
                            __suboption[__suboption_count++] = ch;
                        }
                        break;
                    default:            // unexpected byte! ignore it

                        break;
                }
                __receiveState = _STATE_SB;
                continue;/* TERMINAL-TYPE option (end)*/
        }

        break;
    }

    return ch;
}
